const lo = (a, b) => Math.min(a, b), hi = (a, b) => Math.max(a, b);

// ---- pump islands (curb, bollards) -----------------------------------------------------------------------------------
/**
 * A raised pump-island curb at x..x+1, z0..z1 (polished_andesite, y=1) with a yellow bollard on each corner of the two
