// ---- road paint -------------------------------------------------------------------------------------------------------
/** The yellow centre line along z (default z=2) from x0 to x1: 3 on, 3 off, starting on at x0, on the asphalt at y=0. */
export function centre_dashes(g, x0, x1, z = 2, opts = {}) {
  const cells = [];
